package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxFile *os.File
var taxScanner *bufio.Scanner
var currentRec TaxRec
var inputDone bool

func formatEdited(v decimal.Decimal, pic string) string {
	// split pic
	dotIdx := strings.Index(pic, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		decPic = ""
	}
	decimalDigits := len(decPic)
	// count integer placeholders
	integerDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			integerDigits++
		}
	}
	neg := v.IsNegative()
	abs := v.Abs()
	// Round to decimalDigits to get string representation (MOVE would pad/truncate)
	// Use Round to keep expected behaviour
	scaled := abs.Round(int32(decimalDigits))
	s := scaled.StringFixed(int32(decimalDigits))
	var intRaw, fracRaw string
	if decimalDigits > 0 {
		parts := strings.SplitN(s, ".", 2)
		intRaw = parts[0]
		if len(parts) > 1 {
			fracRaw = parts[1]
		} else {
			fracRaw = strings.Repeat("0", decimalDigits)
		}
		// ensure frac length
		if len(fracRaw) < decimalDigits {
			fracRaw = fracRaw + strings.Repeat("0", decimalDigits-len(fracRaw))
		} else if len(fracRaw) > decimalDigits {
			fracRaw = fracRaw[:decimalDigits]
		}
	} else {
		intRaw = s
		// remove possible dot
		if idx := strings.Index(intRaw, "."); idx >= 0 {
			intRaw = intRaw[:idx]
		}
		fracRaw = ""
	}
	// handle high-order truncation and left pad with zeros to integerDigits
	if len(intRaw) > integerDigits {
		intRaw = intRaw[len(intRaw)-integerDigits:]
	} else if len(intRaw) < integerDigits {
		intRaw = strings.Repeat("0", integerDigits-len(intRaw)) + intRaw
	}
	// build intPic mapping
	// intRaw provides digits in order for Z/9 placeholders
	var outInt strings.Builder
	digitIdx := 0
	significant := false
	for _, ch := range intPic {
		switch ch {
		case 'Z':
			d := intRaw[digitIdx]
			digitIdx++
			if d != '0' {
				significant = true
			}
			if significant {
				outInt.WriteByte(d)
			} else {
				outInt.WriteByte(' ')
			}
		case '9':
			d := intRaw[digitIdx]
			digitIdx++
			// 9 always prints digit
			outInt.WriteByte(d)
			// after a 9, consider significant true for comma handling already done
			// but no more integer placeholders after last 9 in these pics
		case ',':
			if significant {
				outInt.WriteByte(',')
			} else {
				outInt.WriteByte(' ')
			}
		default:
			outInt.WriteRune(ch)
		}
	}
	result := outInt.String()
	if decimalDigits > 0 {
		result = result + "." + fracRaw
	}
	// handle negative sign: place '-' at leftmost? For simplicity, if negative, replace first space with '-'
	// Not needed for this program (unsigned) but implement
	if neg {
		// find first non-space? COBOL would put sign floating, but we approximate
		// Put '-' just before first digit
		// Search from left for digit
		bs := []byte(result)
		for i := len(bs) - 1; i >= 0; i-- {
			if bs[i] >= '0' && bs[i] <= '9' {
				// find leftmost position to place sign: look for space before
				// simple: put '-' in the last space before digits where possible
				// For now replace the character immediately left of first digit if it's space
				break
			}
		}
		// fallback: prefix
		// attempt to insert '-' by replacing first space
		placed := false
		for i := range bs {
			if bs[i] == ' ' {
				// check if there's a digit to the right
				hasDigit := false
				for j := i + 1; j < len(bs); j++ {
					if bs[j] >= '0' && bs[j] <= '9' {
						hasDigit = true
						break
					}
					if bs[j] == '.' {
						continue
					}
				}
				if hasDigit {
					// put '-' at the rightmost space before digits
					// find last space before first digit
				}
			}
		}
		_ = placed
		// For this task we can simply prepend '-' and drop first char to keep width?
		// But values are never negative.
		result = "-" + result[1:]
	}
	// ensure width equals len(pic)
	if len(result) < len(pic) {
		result = strings.Repeat(" ", len(pic)-len(result)) + result
	} else if len(result) > len(pic) {
		result = result[len(result)-len(pic):]
	}
	return result
}

func storePicOverflow(v decimal.Decimal, intDigits int, decDigits int) decimal.Decimal {
	// truncate to decDigits already done by caller (Round or Truncate)
	// Now apply high-order truncation: keep low-order intDigits digits of integer part
	if intDigits == 0 && decDigits == 0 {
		return decimal.Zero
	}
	neg := v.IsNegative()
	abs := v.Abs()
	// Get string fixed with decDigits
	s := abs.StringFixed(int32(decDigits))
	var intRaw, fracRaw string
	if decDigits > 0 {
		parts := strings.SplitN(s, ".", 2)
		intRaw = parts[0]
		if len(parts) > 1 {
			fracRaw = parts[1]
		} else {
			fracRaw = strings.Repeat("0", decDigits)
		}
	} else {
		// no decimal part
		if idx := strings.Index(s, "."); idx >= 0 {
			intRaw = s[:idx]
		} else {
			intRaw = s
		}
		fracRaw = ""
	}
	// Handle empty intRaw
	if intRaw == "" {
		intRaw = "0"
	}
	if len(intRaw) > intDigits {
		intRaw = intRaw[len(intRaw)-intDigits:]
	}
	// reconstruct
	var recon string
	if decDigits > 0 {
		// ensure frac length
		if len(fracRaw) < decDigits {
			fracRaw = fracRaw + strings.Repeat("0", decDigits-len(fracRaw))
		} else if len(fracRaw) > decDigits {
			fracRaw = fracRaw[:decDigits]
		}
		recon = intRaw + "." + fracRaw
	} else {
		recon = intRaw
	}
	d, err := decimal.NewFromString(recon)
	if err != nil {
		return decimal.Zero
	}
	if neg {
		d = d.Neg()
	}
	return d
}

func parseIncomeField(s string) decimal.Decimal {
	// s length 8, digits only
	// trim spaces
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	// keep only digits and possibly sign
	// Input is unsigned, so just digits
	var digits strings.Builder
	for _, c := range t {
		if c >= '0' && c <= '9' {
			digits.WriteRune(c)
		}
	}
	ds := digits.String()
	if ds == "" {
		return decimal.Zero
	}
	// Remove leading zeros? keep for parsing
	// Parse as integer
	d, err := decimal.NewFromString(ds)
	if err != nil {
		return decimal.Zero
	}
	// implied 2 decimal places
	d = d.Shift(-2)
	return d
}

func READ_PARA() {
	if taxScanner.Scan() {
		line := taxScanner.Text()
		// Pad with spaces on the right to record length 13 if shorter
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		trId := line[0:5]
		trIncomeStr := line[5:13]
		currentRec.TrId = trId
		currentRec.TrIncome = parseIncomeField(trIncomeStr)
		inputDone = false
		WsEofFlag = "N"
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	d10000 := decimal.NewFromInt(10000)
	d40000 := decimal.NewFromInt(40000)
	d1000 := decimal.NewFromInt(1000)
	d7000 := decimal.NewFromInt(7000)
	rate10 := decimal.RequireFromString("0.10")
	rate20 := decimal.RequireFromString("0.20")
	rate30 := decimal.RequireFromString("0.30")

	trIncome := currentRec.TrIncome
	var tax decimal.Decimal
	if trIncome.LessThanOrEqual(d10000) {
		tax = trIncome.Mul(rate10).Round(2)
	} else {
		if trIncome.LessThanOrEqual(d40000) {
			diff := trIncome.Sub(d10000)
			tax = d1000.Add(diff.Mul(rate20)).Round(2)
		} else {
			diff := trIncome.Sub(d40000)
			tax = d7000.Add(diff.Mul(rate30)).Round(2)
		}
	}
	WsTax = storePicOverflow(tax, 7, 2)
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (without ROUNDED -> TRUNCATE)
	netRaw := trIncome.Sub(WsTax).Truncate(2)
	WsNet = storePicOverflow(netRaw, 7, 2)
	// ADD WS-TAX TO WS-TOTAL-TAX
	sum := WsTotalTax.Add(WsTax)
	WsTotalTax = storePicOverflow(sum.Truncate(2), 9, 2)
	WsCount = (WsCount + 1) % 1000
	// MOVE to edited
	WsIncEd = formatEdited(trIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	// DISPLAY TR-ID " " WS-INC-ED " " WS-TAX-ED " " WS-NET-ED
	fmt.Printf("%s %s %s %s\n", currentRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READ_PARA()
}

func main() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer taxFile.Close()
	taxScanner = bufio.NewScanner(taxFile)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	taxScanner.Buffer(buf, 10*1024*1024)

	// MAIN-PARA
	// OPEN INPUT TAX-FILE
	// PERFORM READ-PARA
	READ_PARA()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE TAX-FILE already deferred
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	// WS-COUNT is PIC 9(3) zero-padded
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}
